import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>При размере 100 КБ выбор формата решает, будет ли изображение выглядеть чисто или размыто. Один и тот же снимок в JPG, PNG и WebP при одинаковом весе выглядит по-разному.</p>\n<p>Форматы работают по разным принципам. JPG и WebP выбрасывают данные, которые глаз почти не замечает, а PNG хранит всё без потерь — и платит за это весом.</p>\n<p>Это сравнение покажет, как каждый формат ведёт себя при 100 КБ, где каждый выигрывает и как выбрать правильно с первой попытки. А проверить выбор на своём файле поможет инструмент <a href=\"/ru/szhat-izobrazhenie-do-100-kb/\">Сжать изображение до 100 КБ</a>.</p>\n<h2 id=\"how-each-format-works\">Как работает каждый формат</h2>\n<p>JPG сжимает с потерями: он делит изображение на блоки и упрощает детали внутри каждого блока. Плавные тона и градиенты переносятся хорошо, а резкие края страдают.</p>\n<p>WebP тоже сжимает с потерями, но использует более современный метод. Он точнее предсказывает соседние пиксели, поэтому при том же весе сохраняет больше деталей.</p>\n<p>PNG сжимает без потерь: он хранит каждый пиксель точно. Для плоской графики это идеально, а для фото — дорого, потому что каждый оттенок сохраняется полностью.</p>\n<p>Разница в подходе и решает всё при 100 КБ. Формат с потерями может «договориться» о весе, а PNG — нет.</p>\n<h2 id=\"jpg-at-100kb\">JPG при 100 КБ</h2>\n<p>JPG — самый безопасный выбор при 100 КБ. Его открывает всё: порталы, почта, старые системы и любые браузеры.</p>\n<p>Для фото JPG при 100 КБ выглядит чисто. Тона кожи плавные, цвета естественные, а лёгкая мягкость заметна, только если приблизить изображение.</p>\n<p>Слабое место JPG — резкие края и мелкий текст. На контрастных границах могут появиться ореолы, а крошечные буквы — слегка размыться.</p>\n<p>Градиенты в JPG тоже страдают: плавное небо может показать слабые полосы. При 100 КБ полосы едва заметны, но при близком рассмотрении их видно.</p>\n<h2 id=\"webp-at-100kb\">WebP при 100 КБ</h2>\n<p>WebP часто даёт самый чистый результат при 100 КБ. Края резче, чем у JPG, а градиенты — глаже, при том же весе файла.</p>\n<p>Для фото разница невелика, но заметна при сравнении рядом. Волосы и ткань сохраняют чуть больше текстуры, чем в JPG.</p>\n<p>Для скриншотов преимущество WebP больше. Текст интерфейса остаётся читаемым там, где JPG уже размывает буквы.</p>\n<p>Подвох — в совместимости. Некоторые старые порталы, почтовые клиенты и системы не принимают WebP, поэтому всегда проверяйте правила места назначения.</p>\n<h2 id=\"png-at-100kb\">PNG при 100 КБ</h2>\n<p>PNG при 100 КБ — это компромисс с жёсткими рамками. Для плоской графики он безупречен: резкие линии, чистые цвета и никакой размытости.</p>\n<p>Для фото PNG почти всегда проигрывает. Детальный снимок в PNG может весить мегабайты, и даже сильное уменьшение размеров не доводит его до 100 КБ.</p>\n<p>Единственное настоящее преимущество PNG — прозрачность. Ни JPG, ни обычный WebP для фото не хранят прозрачный фон так же надёжно.</p>\n<p>Если в PNG — фото, конвертируйте его. Автоконвертация в JPG или WebP часто превращает неудачу в чистый результат при 100 КБ.</p>\n<h2 id=\"photos-compared\">Фото: сравнение рядом</h2>\n<p>Возьмите портрет и сожмите его до 100 КБ в трёх форматах. При обычном просмотре все три выглядят хорошо — различия прячутся в деталях.</p>\n<p>Приблизьте волосы: в WebP отдельные пряди видны чуть лучше, в JPG они мягче, а в PNG фото просто не уместилось бы в 100 КБ.</p>\n<p>Посмотрите на кожу: JPG и WebP дают плавные тона, а разница между ними заметна, только если искать её специально.</p>\n<p>Вывод для фото простой: WebP чуть лучше, JPG — самый безопасный, а PNG для фото не подходит.</p>\n<h2 id=\"graphics-compared\">Графика: сравнение рядом</h2>\n<p>Логотип с плоскими цветами и резкими краями — территория PNG. При 100 КБ он остаётся идеально чётким, без единого ореола.</p>\n<p>JPG на той же графике даёт заметные артефакты: края «грязные», а плоские цвета покрыты пятнами. Для логотипа это неприемлемо.</p>\n<p>WebP справляется с графикой лучше JPG, но всё равно проигрывает PNG в резкости краёв. Разница небольшая, но на логотипе её видно.</p>\n<p>Для графики правило обратное: PNG первый, WebP второй, а JPG — только если другого выхода нет.</p>\n<h2 id=\"screenshots-compared\">Скриншоты: сравнение рядом</h2>\n<p>Скриншоты сочетают текст, резкие края и плоские цвета — и это самый сложный тест для форматов при 100 КБ.</p>\n<p>WebP здесь выигрывает: мелкий текст остаётся читаемым, а края интерфейса — резкими. При том же весе он сохраняет больше полезной информации.</p>\n<p>JPG на скриншотах даёт размытые буквы и ореолы вокруг текста. При 100 КБ основной текст ещё читаем, а вот мелкие подписи страдают.</p>\n<p>PNG для скриншота идеален по качеству, но часто не умещается в 100 КБ. Если скриншот простой, с большими плоскими областями, PNG может и пройти.</p>\n<h2 id=\"transparency-compared\">Прозрачность: сравнение</h2>\n<p>Прозрачность нужна логотипам, стикерам и наложениям. Здесь PNG — безусловный лидер: он хранит прозрачность точно, пиксель в пиксель.</p>\n<p>WebP тоже поддерживает прозрачность, и при 100 КБ справляется с ней хорошо. Края могут быть чуть мягче, чем в PNG, но для большинства задач этого достаточно.</p>\n<p>JPG прозрачность не поддерживает вообще. Прозрачный фон при конвертации в JPG станет белым или чёрным, и это уже не исправить.</p>\n<p>Если прозрачность важна, не конвертируйте в JPG. Выбирайте между PNG и WebP в зависимости от лимита веса.</p>\n<h2 id=\"which-format-when\">Какой формат и когда выбирать</h2>\n<p>Фото для портала или резюме: JPG, если правила не уточняют формат. Это самый безопасный выбор, который примут везде.</p>\n<p>Фото для блога или сайта, где WebP разрешён: WebP. Он даёт чуть более чистый результат при том же весе.</p>\n<p>Логотип, иконка или диаграмма: PNG. Резкость краёв важнее экономии веса, а плоская графика в PNG весит немного.</p>\n<p>Скриншот с текстом: WebP, если принимается, иначе JPG. PNG — только если скриншот простой и укладывается в 100 КБ.</p>\n<p>Изображение с прозрачностью: PNG или WebP. JPG исключён полностью, потому что он не хранит прозрачность.</p>\n<h2 id=\"testing-method\">Как тестировать форматы честно</h2>\n<p>Сожмите одно и то же изображение во всех трёх форматах до 100 КБ. Сравнивайте только файлы одинакового веса — иначе сравнение нечестное.</p>\n<p>Смотрите на результат в полном размере и на том экране, где его увидят. Миниатюры скрывают различия, которые заметны в полном размере.</p>\n<p>Проверяйте именно важные детали: глаза на портрете, мелкий текст на скриншоте, края на логотипе. Общий вид обманчив.</p>\n<p>Запишите победителя для каждого типа изображений. В следующий раз выбор займёт секунды.</p>\n<p>Тестируйте на реальном изображении, а не на чужом примере. Ваш снимок с вашим светом и фоном ведёт себя иначе, чем образец из статьи.</p>\n<h2 id=\"colour-depth\">Глубина цвета</h2>\n<p>Глубина цвета определяет, сколько оттенков может хранить изображение. JPG и WebP хранят миллионы цветов, а PNG — столько же, но без потерь.</p>\n<p>При 100 КБ глубина цвета страдает первой в форматах с потерями. Плавные градиенты упрощаются, и на небе появляются полосы.</p>\n<p>WebP справляется с градиентами лучше JPG при том же весе. Если полосы вас беспокоят, попробуйте WebP первым.</p>\n<p>Для фото с богатыми цветами — закат, ткань, еда — разница между JPG и WebP заметнее, чем для обычного портрета.</p>\n<p>Для плоской графики глубина цвета не важна: там всего несколько цветов, и любой формат справляется легко.</p>\n<h2 id=\"sharpness-vs-smoothness\">Резкость против плавности</h2>\n<p>Сжатие всегда балансирует резкость и плавность. Резкие края требуют данных, а плавные области сжимаются дёшево.</p>\n<p>JPG отдаёт предпочтение плавности: кожа и фон выглядят гладко, а края слегка смягчаются. Для портретов это хорошо.</p>\n<p>WebP лучше сохраняет резкость при той же плавности. Поэтому он выигрывает на скриншотах и графике с текстом.</p>\n<p>PNG не жертвует ничем: он сохраняет и резкость, и плавность полностью. Цена — вес, который для фото становится неподъёмным.</p>\n<p>Выбирайте по содержанию: резкость важна для текста, плавность — для лиц. Формат должен подстраиваться под изображение, а не наоборот.</p>\n<h2 id=\"format-myths\">Мифы о форматах</h2>\n<p>Миф первый: PNG всегда качественнее. Для графики — да, а для фото при 100 КБ PNG просто не умещается и проигрывает.</p>\n<p>Миф второй: WebP всегда лучше JPG. Чаще да, но не везде: некоторые порталы его не принимают, и тогда лучший формат — тот, который примут.</p>\n<p>Миф третий: конвертация формата всегда ухудшает качество. Конвертация PNG с фото в JPG при 100 КБ улучшает результат: файл наконец-то укладывается в лимит.</p>\n<p>Миф четвёртый: больший файл всегда лучше. Файл на 200 КБ в неудачном формате может выглядеть хуже, чем файл на 100 КБ в подходящем.</p>\n<p>Проверяйте мифы на своих изображениях. Один тест стоит больше десяти статей.</p>\n<h2 id=\"archiving-100kb\">Архивирование копий на 100 КБ</h2>\n<p>Копии на 100 КБ — это рабочие файлы, а не архив. Храните оригиналы отдельно и в полном качестве.</p>\n<p>Если архивируете и сжатые копии, указывайте формат в имени файла. Имя вроде photo-100kb-webp.jpg сразу говорит, что внутри.</p>\n<p>Не конвертируйте архивные копии туда-сюда между форматами. Каждая конвертация с потерями добавляет повреждения.</p>\n<p>Для архива фото лучше всего подходит оригинал в исходном формате. Сжатые копии создаются заново, когда понадобятся.</p>\n<p>Если места мало, храните оригиналы в облаке, а копии на 100 КБ — локально. Так баланс между безопасностью и удобством сохраняется.</p>\n<h2 id=\"quick-reference\">Быстрая шпаргалка</h2>\n<p>Фото, портал, неизвестные правила: JPG. Безопасно, принято везде, качество при 100 КБ хорошее.</p>\n<p>Фото, блог, WebP разрешён: WebP. Чуть чище JPG при том же весе, особенно на краях и текстурах.</p>\n<p>Логотип, диаграмма, плоская графика: PNG. Идеальная резкость, а вес плоской графики невелик.</p>\n<p>Скриншот с текстом: WebP, иначе JPG. Текст — главный приоритет, и WebP сохраняет его лучше.</p>\n<p>Прозрачность: PNG или WebP. JPG не подходит, потому что не хранит прозрачный фон.</p>\n<h2 id=\"lossy-vs-lossless\">Сжатие с потерями и без потерь</h2>\n<p>Сжатие с потерями выбрасывает данные навсегда. JPG и WebP работают так: они решают, какие детали глаз не заметит, и удаляют их.</p>\n<p>Сжатие без потерь сохраняет всё. PNG работает так: файл можно распаковать обратно пиксель в пиксель, без единой потери.</p>\n<p>При 100 КБ сжатие с потерями почти всегда выигрывает для фото. Оно «договаривается» о весе, а PNG — нет.</p>\n<p>Для графики без потерь выигрывает PNG. Там данных немного, и сохранение каждого пикселя стоит недорого.</p>\n<p>Понимание разницы помогает выбирать: фото — с потерями, графика — без потерь, скриншоты — где-то посередине.</p>\n<h2 id=\"browser-support\">Поддержка форматов в браузерах</h2>\n<p>JPG поддерживают все браузеры без исключения, включая самые старые. Это ещё одна причина, почему JPG — безопасный выбор.</p>\n<p>WebP поддерживают все современные браузеры. Проблемы бывают только со старыми системами и некоторыми почтовыми клиентами.</p>\n<p>PNG тоже поддерживают везде. Вопрос не в браузере, а в весе: браузер покажет PNG-фото, но файл может оказаться слишком тяжёлым для портала.</p>\n<p>Для изображений в интернете проверяйте не только браузер, но и место назначения. Портал важнее браузера: именно он решает, принять файл или нет.</p>\n<p>Когда сомневаетесь, держите под рукой обе версии — JPG и WebP. Загрузите ту, которую примет портал.</p>\n<h2 id=\"future-formats\">Форматы будущего</h2>\n<p>Появляются новые форматы вроде AVIF, которые обещают ещё лучшее качество при меньшем весе. Но порталы принимают их медленно.</p>\n<p>Для форм и порталов будущее пока не наступило: JPG и WebP остаются практичным выбором, а PNG — выбором для графики.</p>\n<p>Следите за правилами ваших порталов. Когда они начнут принимать AVIF, сравнение придётся делать заново.</p>\n<p>Не гонитесь за новинками ради самих новинок. Формат, который принимает ваш портал сегодня, важнее формата, который станет стандартом завтра.</p>\n<p>А пока что освойте тройку JPG, PNG и WebP. Этих трёх форматов хватает для почти всех задач при 100 КБ.</p>\n<h2 id=\"how-quality-is-picked\">Как выбирается качество при 100 КБ</h2>\n<p>Инструмент не угадывает качество: он запускает бинарный поиск. Он проверяет уровни качества, пока не найдёт самый высокий, который укладывается в 100 КБ.</p>\n<p>Поиск начинается с середины и делит диапазон пополам при каждой проверке. За семь проверок он находит лучшее качество для вашего изображения.</p>\n<p>Поэтому лучшее качество может быть 63 процента, а не круглые 60 или 70. Поиск находит точную точку, а не ближайшее круглое число.</p>\n<p>Формат влияет на поиск: PNG при качестве 90 может весить больше, чем JPG при качестве 50. Поэтому поиск выполняется отдельно для каждого формата.</p>\n<p>Когда поиск не находит подходящего качества, инструмент уменьшает размеры. Качество — первый рычаг, размеры — второй.</p>\n<p>Когда работаете с новым типом изображений, начните с маленького теста: сожмите один файл в трёх форматах и сравните их рядом. Один тест стоит больше десяти статей.</p>\n<p>Не забывайте про место назначения: формат, который принимает ваш портал сегодня, важнее формата, который станет стандартом завтра. Проверяйте правила перед каждой отправкой.</p>\n<p>Если изображение содержит и фото, и текст — например, скриншот с фотографией внутри, — отдайте приоритет тексту. Размытое фото простят, а нечитаемый текст — нет.</p>\n<p>Храните тестовые файлы с понятными именами: photo-test-jpg.jpg, photo-test-webp.webp. Через месяц вы сможете вспомнить, какой формат выиграл и почему.</p>\n<p>Для командной работы запишите выбор формата в общую заметку. Когда каждый автор выбирает формат по-своему, сайт выглядит несогласованно.</p>\n<p>И помните: формат — это инструмент, а не религия. Лучший формат — тот, который даёт чистый результат при вашем лимите и принимается вашим порталом.</p>\n<p>Когда выбираете формат для нового проекта, начните с правил места назначения, а не с привычки. Портал или платформа решают, а не ваши предпочтения.</p>\n<p>Тестируйте форматы на своих изображениях, а не на чужих примерах. Ваш снимок с вашим светом ведёт себя иначе, чем образец из статьи.</p>\n<p>Быстрый тест выбора: фото для портала — JPG, фото для блога с поддержкой WebP — WebP, логотип — PNG, скриншот с текстом — WebP. Четыре правила покрывают почти все задачи.</p>\n<p>Когда появится AVIF в ваших порталах, сравнение придётся делать заново. А пока что тройки JPG, PNG и WebP хватает для почти всех задач при 100 КБ.</p>\n<p>Полное руководство по этому размеру читайте в статье <a href=\"/ru/blog/kak-szhat-izobrazhenie-do-100-kb-polnoe-rukovodstvo/\">Как сжать изображение до 100 КБ: полное руководство</a>. Практические шаги — в статье <a href=\"/ru/blog/kak-umenshit-izobrazhenie-do-100-kb/\">Как уменьшить изображение до 100 КБ</a>. Конвертировать форматы можно в инструменте <a href=\"/ru/konvertirovat-izobrazhenie/\">конвертации изображений</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Всегда ли WebP лучше JPG при 100 КБ?","answer":"Чаще да, но не всегда. WebP обычно чуть чище при том же весе, особенно на краях и скриншотах. Но некоторые старые порталы и почтовые клиенты не принимают WebP — тогда лучше JPG, который примут везде."},{"question":"Почему моё фото в PNG при 100 КБ выглядит хуже?","answer":"Потому что PNG хранит фото без потерь и не может сбросить достаточно веса. Чтобы уместиться в 100 КБ, PNG приходится сильно уменьшать размеры, и фото теряет детали. Конвертация в JPG или WebP решает проблему."},{"question":"Можно ли конвертировать PNG-фото в JPG, чтобы достичь 100 КБ?","answer":"Да, и это часто лучший шаг. Автоконвертация в инструменте переводит PNG с фото в JPG или WebP перед сжатием. Не конвертируйте только PNG с прозрачностью: JPG её не сохраняет."},{"question":"Сохраняет ли WebP те же цвета, что и JPG?","answer":"В целом да: оба формата хранят миллионы цветов. WebP даже чуть лучше справляется с градиентами при том же весе, поэтому плавные переходы цвета выглядят чище. Заметной разницы в цветопередаче между ними нет."},{"question":"Какой формат выбрать для отсканированного документа при 100 КБ?","answer":"Для скана с текстом лучше WebP, если портал его принимает: мелкий текст остаётся читаемым. Если WebP не принимается, берите JPG. PNG подходит только для простых сканов с большими плоскими областями."},{"question":"Ухудшит ли конвертация форматов качество изображения?","answer":"Конвертация с потерями добавляет небольшое ухудшение, но при 100 КБ она часто улучшает результат: файл наконец-то укладывается в лимит. Главное — конвертировать один раз из оригинала, а не пережимать уже сжатую копию."}];
